import{_ as t,o,c as d,a0 as a}from"./chunks/framework.jwovEGr5.js";const b=JSON.parse('{"title":"Eval governance (C08 L80)","description":"","frontmatter":{},"headers":[],"relativePath":"eval/GOVERNANCE.md","filePath":"eval/GOVERNANCE.md"}'),r={name:"eval/GOVERNANCE.md"};function c(n,e,i,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="eval-governance-c08-l80" tabindex="-1">Eval governance (C08 L80) <a class="header-anchor" href="#eval-governance-c08-l80" aria-label="Permalink to &quot;Eval governance (C08 L80)&quot;">​</a></h1><p>Process-supervisor evaluation policy for sharecli. Supersedes ad-hoc bench additions; Harbor/SWE-bench agent corpora remain out of scope until product scope changes.</p><h2 id="in-scope-eval-family" tabindex="-1">In-scope eval family <a class="header-anchor" href="#in-scope-eval-family" aria-label="Permalink to &quot;In-scope eval family&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>Microbench</td><td><code>benches/*.rs</code></td><td>Criterion hot paths (config, pool, metrics, auth)</td></tr><tr><td>Macro / load</td><td><code>scripts/load/</code></td><td>HTTP burst against live <code>sharecli serve</code></td></tr><tr><td>Latency toolbelt</td><td><code>scripts/bench/</code></td><td>Hyperfine harnesses (e.g. <code>/healthz</code>)</td></tr><tr><td>Repro</td><td><code>docs/eval/REPRO.md</code></td><td>SHA, lockfile, toolchain, <code>SHARECLI_BENCH_SEED</code></td></tr><tr><td>Baselines</td><td><code>docs/eval/baselines/</code></td><td>Committed Criterion means + optional hyperfine JSON</td></tr><tr><td>Trends</td><td><code>docs/eval/TRENDS.md</code></td><td>Nightly Criterion artifact contract</td></tr><tr><td>SLO budgets</td><td><code>docs/ops/SLO.md</code></td><td>BENCH-* / LOAD-* rows linked to harnesses</td></tr></tbody></table><p><strong>Current Criterion family (supervisor tasks):</strong> <code>config_parse</code>, <code>pool_list</code>, <code>prometheus_render</code>, <code>jwt_auth_validate</code> (FR-012 JWT validate).</p><h2 id="n-a-surfaces-adr-map" tabindex="-1">N/A surfaces (ADR map) <a class="header-anchor" href="#n-a-surfaces-adr-map" aria-label="Permalink to &quot;N/A surfaces (ADR map)&quot;">​</a></h2><p>Governed by <a href="./../adr/0002-eval-surface-out-of-scope.html"><code>docs/adr/0002-eval-surface-out-of-scope.md</code></a>.</p><table tabindex="0"><thead><tr><th>Pillar</th><th>Surface</th><th>Status</th></tr></thead><tbody><tr><td>L75</td><td>Cross-language (Py/Go/TS) eval parity</td><td>N/A</td></tr><tr><td>L76</td><td>Harbor / portage / Terminal-Bench</td><td>N/A</td></tr><tr><td>L77</td><td>Compression / spec-extraction benches</td><td>N/A</td></tr><tr><td>L78</td><td>LLM token-burn / cost tracking</td><td>N/A</td></tr><tr><td>L71 (agent corpora)</td><td>SWE-bench / SWE-RL task sets</td><td>N/A</td></tr></tbody></table><p>Auditors score L75–L78 as <strong>deferred / N/A</strong>, not missing product. C08 lifts come from supervisor benches + load + REPRO + CI gate + this doc.</p><h2 id="how-to-add-a-bench" tabindex="-1">How to add a bench <a class="header-anchor" href="#how-to-add-a-bench" aria-label="Permalink to &quot;How to add a bench&quot;">​</a></h2><ol><li><strong>Pick a real hot path</strong> — config parse, pool list, metrics render, JWT validate, audit emit, etc. Prefer public APIs in <code>sharecli::</code> crates; do not bench private internals.</li><li><strong>Add <code>benches/&lt;name&gt;.rs</code></strong> + <code>[[bench]]</code> in root <code>Cargo.toml</code> (<code>harness = false</code>).</li><li><strong>Document</strong> — header comment with draft SLO; row in <code>docs/ops/SLO.md</code> (<code>BENCH-N</code>); link from <code>docs/eval/README.md</code>.</li><li><strong>Baseline</strong> — run locally with pins from <code>REPRO.md</code>, then <code>python3 scripts/seed-bench-baseline.py</code> and commit <code>docs/eval/baselines/criterion-baseline.json</code> with ~2× headroom for CI variance.</li><li><strong>Wire CI</strong> — <code>jwt_auth_validate</code> is included in <code>.github/workflows/bench.yml</code> (<code>criterion</code>, <code>bench-gate</code>, <code>bench-nightly</code>) with baseline key <code>jwt_validate_rs256</code>. Merge gate ownership: <strong>C08 lane / perf maintainers</strong>; flake quarantine per <code>docs/testing/flake-policy.md</code>.</li></ol><p>Load scripts follow the same pattern under <code>scripts/load/</code> with <code>LOAD-*</code> SLO rows and <code>scripts/load/README.md</code>.</p><h2 id="ci-gate-ownership" tabindex="-1">CI gate ownership <a class="header-anchor" href="#ci-gate-ownership" aria-label="Permalink to &quot;CI gate ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Job</th><th>Owner intent</th><th>Gate?</th></tr></thead><tbody><tr><td><code>criterion</code> (soft)</td><td>Advisory Criterion on PR/push</td><td>No (<code>continue-on-error</code>)</td></tr><tr><td><code>bench-gate</code></td><td><code>check-bench-baseline.py</code> vs committed JSON</td><td><strong>Yes</strong> (50% max regression)</td></tr><tr><td><code>bench-nightly</code></td><td><code>export-trend.py</code> + hyperfine JSON → Actions artifacts</td><td>No (longitudinal)</td></tr><tr><td><code>hyperfine-healthz</code> (soft)</td><td>Live <code>/healthz</code> hyperfine JSON on PR/push</td><td>No (<code>continue-on-error</code>)</td></tr></tbody></table><p>Hyperfine JSON (<code>SHARECLI_HYPERFINE_OUT</code>) is produced locally and in CI artifacts (<code>hyperfine-healthz-&lt;sha&gt;.json</code>); see <code>TRENDS.md</code> and <code>scripts/bench/README.md</code>.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Lane evidence: <code>audit/.lane-c08/C08.md</code></li><li>Rubric: <code>audit/rubric/audit-30-pillar/audit-30-pillar-L71-L80-eval-coverage.md</code></li><li>FR traceability: <code>docs/specs/TRACEABILITY.md</code> (FR-002 config, FR-012 JWT)</li></ul>',17)])])}const u=t(r,[["render",c]]);export{b as __pageData,u as default};
